import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    # Count opponent defections overall and recently
    total_opp_d = sum(1 for a in opp if a == 'D')
    recent_window = min(n, 10)
    recent_opp_d = sum(1 for a in opp[-recent_window:] if a == 'D')

    last_opp = opp[-1]
    last_me = me[-1]

    # Strategy logic

    # 1. Exploit Pure Cooperators aggressively in the endgame or randomly
    if total_opp_d == 0:
        if n >= 90:
            # Defect frequently against pure cooperators near the end
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        elif n >= 70:
            # Moderate exploitation
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        else:
            # Very rare probing to maintain CC flow but check consistency
            if rng.random() < 0.02:
                return 'D'
            return 'C'

    # 2. Handle Persistent Defectors
    # If opponent has defected significantly more than they cooperated
    if total_opp_d > n / 2 + 2 or (n >= 6 and total_opp_d >= 5):
        # Mostly defect, but probe for change occasionally
        if last_opp == 'C':
            # They just cooperated after being mostly D. 
            # Try to see if this is a real shift or noise/trap.
            if recent_opp_d <= 2: # Recent behavior shifted
                 return 'C'
            return 'D'
        else:
            # They are still defecting
            # Occasional cooperation to break DD loops if we are stuck
            if last_me == 'D' and last_opp == 'D':
                if rng.random() < 0.1:
                    return 'C'
            return 'D'

    # 3. Mixed/Reciprocal Opponents
    # Core logic: Tit-for-Tat with Forgiveness and Strategic Endgame

    if last_opp == 'D':
        # Retaliate unless it looks like a mistake or isolated event
        # Check if opponent was cooperative before this D
        prev_opp_c_count = sum(1 for a in opp[:-1] if a == 'C')
        prev_n = n - 1

        # If they were mostly C before this single D, forgive sometimes
        if prev_n > 0 and (prev_opp_c_count / prev_n) > 0.7:
            if rng.random() < 0.4:
                return 'C'

        # If we have been in a long DD loop, try to break out
        if last_me == 'D':
            # Count consecutive DDs
            dd_run = 0
            for i in range(n-1, -1, -1):
                if me[i] == 'D' and opp[i] == 'D':
                    dd_run += 1
                else:
                    break

            if dd_run >= 3:
                # Break the cycle with high probability
                if rng.random() < 0.7:
                    return 'C'

        return 'D'

    else:
        # Last opponent action was C
        # Consider cooperating, but exploit opportunities

        # Endgame exploitation against mostly cooperative opponents
        if n > 85:
            # If they have low defection count so far, start defecting
            if total_opp_d < 3:
                if rng.random() < 0.6:
                    return 'D'
            elif total_opp_d < 6:
                if rng.random() < 0.3:
                    return 'D'

        # Mid-game occasional probe/exploit if trust is established
        if 40 < n < 85:
            # If we have had many CCs recently, maybe slip a D?
            # Risky against TFT-like strategies. Keep low prob.
            recent_cc = sum(1 for i in range(max(0, n-5), n) if me[i]=='C' and opp[i]=='C')
            if recent_cc >= 4:
                if rng.random() < 0.05:
                    return 'D'

        return 'C'
